script.text:

function init$&Identity;Filter$(f) {
}
function active$&Identity;Filter$(f) {
	var g = f.grid, w = g.get_element().parentForm, r = g._activeRow;
	f.setItemValues('ma_hd', [g._getItemValue(r, g._getColumnOrder('ma_hd'))]);

	f.add_commandEvent(on$&Identity;$ExecuteCommand);
	f.add_onResponseComplete(on$&Identity;$ResponseComplete);

	f.request('mData', 'mData', ['ma_hd'], null);
	f._findButton('Ok').style.display = 'none';
}
function close$&Identity;Filter$(f) {
	try {f.remove_commandEvent(on$&Identity;$ExecuteCommand);} catch (ex) {}
	try {f.remove_onResponseComplete(on$&Identity;$ResponseComplete);} catch (ex) {}
}
function on$&Identity;$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result, id = f.get_id();
	switch (context) {
		case 'mData':
			for (var i = 0; i < result.length; i++) {
				f.setItemValue(result[i].Name, result[i].Value);
			}
			break;
		default:
			break;
	}
}
function on$&Identity;$ExecuteCommand(sender, e) {
	var action = e.type.Action, f = sender;
	switch (action) {
		default:
			break;
	}
}
function on$&Identity;Filter$Retrieve$QueryComplete(f) {
	var g = f.grid;
	set$&Identity;Filter$FormScript(g);
}
function set$&Identity;Filter$FormScript(g) {g._formScript = 'show$&Identity;Filter$QueryComplete(this)';}
function show$&Identity;Filter$QueryComplete(g) {
	g._memvars = [];
	g._arrValue = [];
	g._focusWhenTabChanged();
	g.goToPage(-1);
}
/* </flatten> */
